// server/connections.server.ts
var COACH_ROLE = "coach";
var ATHLETE_ROLE = "student_athlete";
var COACH_VERIFIED_PERMISSION = "sessions:verify";
var PAGE_DEFAULT = 50;
var PAGE_MAX = 100;
var SEARCH_MIN_CHARS = 2;
